+package com.example.contact;
+
+import java.util.regex.Pattern;
+
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.Shortcuts;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final Pattern EMAIL = Pattern
+            .compile("^[^@\\s]+@[^@\\s.]+(\\.[^@\\s.]+)+$");
+
+    private final MessageStore store;
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<MessageStore.Entry> grid = new Grid<>();
+    private boolean clearing;
+    private boolean leaveConfirmed;
+
+    public ContactView(MessageStore store) {
+        this.store = store;
+        add(new H1("Contact"), new RouterLink("About", AboutView.class));
+
+        grid.addColumn(MessageStore.Entry::name).setHeader("Name");
+        grid.addColumn(MessageStore.Entry::message).setHeader("Message");
+
+        for (var f : new com.vaadin.flow.component.HasValue<?, ?>[] { name,
+                email, phone, message }) {
+            f.addValueChangeListener(e -> {
+                if (!clearing) {
+                    send.setEnabled(true);
+                }
+            });
+        }
+        send.addClickListener(e -> submit());
+        Shortcuts.addShortcutListener(this, this::submit, Key.ENTER);
+
+        add(name, email, phone, message, send, grid);
+        refresh();
+    }
+
+    private void refresh() {
+        grid.setItems(store.all());
+    }
+
+    private boolean hasContent() {
+        return !name.isEmpty() || !email.isEmpty() || !phone.isEmpty()
+                || !message.isEmpty();
+    }
+
+    private void submit() {
+        if (!send.isEnabled()) {
+            return;
+        }
+        for (var f : new com.vaadin.flow.component.HasValidation[] { name,
+                email, phone, message }) {
+            f.setInvalid(false);
+        }
+        String n = name.getValue();
+        String em = email.getValue() == null ? "" : email.getValue().trim();
+        String ph = phone.getValue() == null ? "" : phone.getValue().trim();
+        String msg = message.getValue() == null ? "" : message.getValue();
+        boolean ok = true;
+        if (n == null || n.isBlank()) {
+            fail(name, "Name is required");
+            ok = false;
+        }
+        if (!em.isEmpty() && !EMAIL.matcher(em).matches()) {
+            fail(email, "Enter a valid e-mail address");
+            ok = false;
+        } else if (em.isEmpty() && ph.isEmpty()) {
+            fail(email, "Give an e-mail address or a phone number");
+            ok = false;
+        }
+        if (msg.isBlank()) {
+            fail(message, "Message is required");
+            ok = false;
+        } else if (msg.length() > 500) {
+            fail(message, "Message must be at most 500 characters");
+            ok = false;
+        }
+        if (!ok) {
+            return;
+        }
+        store.add(new MessageStore.Entry(n, em, ph, msg));
+        clearing = true;
+        try {
+            name.clear();
+            email.clear();
+            phone.clear();
+            message.clear();
+        } finally {
+            clearing = false;
+        }
+        for (var f : new com.vaadin.flow.component.HasValidation[] { name,
+                email, phone, message }) {
+            f.setInvalid(false);
+        }
+        send.setEnabled(false);
+        refresh();
+        Notification.show("Message sent");
+    }
+
+    private void fail(com.vaadin.flow.component.HasValidation f, String msg) {
+        f.setErrorMessage(msg);
+        f.setInvalid(true);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (leaveConfirmed || !hasContent()) {
+            return;
+        }
+        var postponed = event.postpone();
+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Discard unsent message?");
+        Button keep = new Button("Keep editing", e -> dialog.close());
+        Button discard = new Button("Discard", e -> {
+            leaveConfirmed = true;
+            dialog.close();
+            postponed.proceed();
+        });
+        dialog.getFooter().add(keep, discard);
+        dialog.open();
+    }
+}
